      const why = `GET ${path} page ${page} failed with status ${status}`;
      throw (status === 401 || status === 403)
        ? grantError(`${why} — the fleet PAT is unusable or lacks the scope this read needs`)
        : new Error(why);
    }"""
assert old2 in s; s=s.replace(old2,new2,1)

old3="""    throw new Error(`writing ${fullName}:${path} returned ${status} — the fleet PAT needs Contents WRITE on this repo (${json?.message ?? 'no message'})`);"""
new3="""    throw grantError(`writing ${fullName}:${path} returned ${status} — the fleet PAT needs Contents WRITE on this repo (${json?.message ?? 'no message'})`);"""
assert old3 in s; s=s.replace(old3,new3,1)
open(p,'w').write(s)
print('ok')
