  python3 - "$f" <<'PY'
import re,sys
p=sys.argv[1]; s=open(p).read()
m=re.search(r"main\(\)\.catch\(\(e\) => \{ console\.error\(`([a-z-]+) failed: \$\{e\.message\}`\); process\.exit\(1\); \}\);", s)
if not m: print('SKIP', p); raise SystemExit
name=m.group(1)
s=s[:m.start()]+f"main().catch((e) => fleetWorkerFailed('{name}', e));"+s[m.end():]
# add import
if 'fleetWorkerFailed' not in s.split('main().catch')[0]:
    lines=s.split('\n')
    for i,l in enumerate(lines):
        if l.startswith('import ') and 'pathToFileURL' in l:
            lines.insert(i+1, "import { fleetWorkerFailed } from '../../fleet-api.mjs';")
            break
    else:
        raise SystemExit('no anchor '+p)
    s='\n'.join(lines)
open(p,'w').write(s); print('ok', p)
PY
done

